function y = mfun_ovhz_rate_limiter(u, p)
%MFUN_OVHZ_RATE_LIMITER Block RateLimiter of the control system.
%   RateLimiter of motulator. Generated by motulator_export from the MATLAB port of
%   motulator. The parameters are the fields of the struct p (from the mask, [] as NaN).
%   The state is in persistent variables.
persistent self
if isempty(self)
    self = rate_limiter_init(p.rate_limit);
end
y = rate_limiter_compute_output(self, p.T_s, u);
self = rate_limiter_update(self, y);
end

function self = rate_limiter_init(rate_limit)
%RATE_LIMITER_INIT Rate limiter (RateLimiter), the falling rate limit being the
%   negative rising one.
self = struct('rate_limit', rate_limit, 'old_y', 0);
end

function y = rate_limiter_compute_output(self, T_s, u)
%RATE_LIMITER_COMPUTE_OUTPUT Limited signal; the state is updated with it by
%   rate_limiter_update.
rate = (u - self.old_y)/T_s;
if rate > self.rate_limit
    y = self.old_y + T_s*self.rate_limit;
elseif rate < -self.rate_limit
    y = self.old_y - T_s*self.rate_limit;
else
    y = u;
end
end

function self = rate_limiter_update(self, y)
%RATE_LIMITER_UPDATE Store the output.
self.old_y = y;
end
